    r = simulate_move(fen, None)
    if r.get("game_over"):
        w = r.get("winner")
        if w == "white": return 100000
        if w == "black": return -100000
        return 0
    sq = r["squares"]
    turn = r["turn"]
    vals = {'p':100,'n':320,'b':330,'r':500,'q':900,'k':0}
    score = 0
    center = {'d4','e4','d5','e5'}
    for coord, p in sq.items():
        v = vals.get(p.lower(),0) + (12 if coord in center else 0)
        score += v if p.isupper() else -v
    if turn == 'black':
        score += 25
    else:
        score -= 25
    return score

fen = "rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR w KQkq - 0 2"
info = simulate_move(fen, None)
legal = sorted(info["legal_moves"])
best = None
bestscore = -10**9
for c in legal:
    after = simulate_move(fen, c)
    if after.get("game_over"):
        cand = eval_pos(after["fen"])
    else:
        replies = after["legal_moves"]
        scores = []
        for rep in replies:
            r2 = simulate_move(after["fen"], rep)
            scores.append(eval_pos(r2["fen"]))
        cand = min(scores)
    if cand > bestscore:
        bestscore = cand
        best = c
print(best, bestscore)
"}

